def _decode_image_url(url: str) -> bytes:
    match = _DATA_URL_RE.match(url)
    if not match:
        raise InferenceError(
            "Image attachments must be base64 data URLs (data:<mime>;base64,<data>)."
        )
    try:
        return base64.b64decode(match.group(1), validate=True)
    except binascii.Error as exc:
        raise InferenceError(f"Invalid base64 image data: {exc}") from exc

def _content_to_engine_message(content: str | list) -> str | Contents:
    """Converts a ChatMessage.content into what Conversation.send_message expects."""
    if isinstance(content, str):
        return content
    parts: list = []
    for part in content:
        if part.type == "text":
            parts.append(Content.Text(part.text))
        elif part.type == "image_url":
            parts.append(Content.ImageBytes(_decode_image_url(part.image_url.url)))
    return Contents.of(*parts) if parts else Contents.empty()

def _extract_reasoning(response: Mapping) -> str:
    reasoning_content = response.get("reasoning_content")
    if isinstance(reasoning_content, str) and reasoning_content:
        return reasoning_content
    channels = response.get("channels")
    if isinstance(channels, dict):
        for key in ("thought", "thinking", "reasoning"):
            value = channels.get(key)
            if isinstance(value, str) and value:
                return value
    parts = response.get("content", [])
    if isinstance(parts, list):
        return "".join(
            part.get("text", "")
            for part in parts
            if isinstance(part, dict) and part.get("type") in ("thinking", "reasoning")
        )
    return ""

def _extract_text(response: Mapping) -> str:
    parts = response.get("content", [])
    if isinstance(parts, str):
        return parts
    if not isinstance(parts, list):
        return ""
    return "".join(
        part.get("text", "")
        for part in parts
        if isinstance(part, dict) and part.get("type") == "text"
    )

def _next_or_sentinel(it):
    # StopIteration can't cross a thread-pool Future boundary (PEP 479):
    # asyncio.to_thread(next, it) turns it into an opaque RuntimeError
    # ("StopIteration ... cannot be raised into a Future"). Catch it here,
    # inside the worker thread, and signal exhaustion with a sentinel instead.
    try:
        return next(it)
    except StopIteration:
        return _STREAM_DONE

def _row_to_event(row: tuple, columns: list[str]) -> dict[str, Any]:
    event = dict(zip(columns, row))
    if isinstance(event.get("ts"), datetime):
        event["ts"] = event["ts"].isoformat() + "Z"
    if "metadata" in event and event["metadata"]:
        try:
            event["metadata"] = json.loads(event["metadata"])
        except (TypeError, json.JSONDecodeError):
            event["metadata"] = {}
    return event

function ErrorsPage() {
  const [range, setRange] = useState<DateRange>(() => presetToRange("7d"));
  const { timeseries, isLoading: seriesLoading, error: seriesError, refetch } =
    useAnalyticsSummary(range);
  const eventsState = useAnalyticsEvents(range, { status: "error" });
  const [selectedRequestId, setSelectedRequestId] = useState<string | null>(null);

  const bucket: "hour" | "day" =
    range.end.getTime() - range.start.getTime() <= 2 * 24 * 60 * 60 * 1000 ? "hour" : "day";

  return (
    <div className="mx-auto flex w-full max-w-5xl flex-col gap-4 p-4 md:p-6">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <h1 className="text-2xl font-semibold tracking-tight">Errors</h1>
        <DateRangePicker value={range} onChange={setRange} />
      </div>

      {seriesError && (
        <Alert variant="destructive">
          <AlertTriangleIcon />
          <AlertTitle>Failed to load chart data</AlertTitle>
          <AlertDescription className="flex items-center justify-between gap-4">
            <span>{seriesError}</span>
            <Button size="sm" variant="outline" onClick={() => void refetch()}>
              Try again
            </Button>
          </AlertDescription>
        </Alert>
      )}

      <Card>
        <CardHeader>
          <CardTitle className="text-sm font-medium">Errors over time</CardTitle>
        </CardHeader>
        <CardContent>
          <MetricChart
            data={timeseries ? timeseries.errors : null}
            bucket={bucket}
            isLoading={seriesLoading}
            valueFormatter={(n) => n.toLocaleString()}
          />
        </CardContent>
      </Card>

      <div>
        <h2 className="mb-2 text-sm font-medium">Failed requests</h2>
        <EventsTable
          page={eventsState.page}
          isLoading={eventsState.isLoading}
          error={eventsState.error}
          onRowClick={(event) => setSelectedRequestId(event.request_id)}
          onRetry={() => void eventsState.refetch()}
          hasNext={eventsState.hasNext}
          hasPrev={eventsState.hasPrev}
          onNext={eventsState.nextPage}
          onPrev={eventsState.prevPage}
        />
      </div>

      <TraceSheet
        requestId={selectedRequestId}
        onOpenChange={(open) => !open && setSelectedRequestId(null)}
      />
    </div>
  );
}

