function useAnalyticsEventDetail(requestId: string | null) {
  const [event, setEvent] = useState<LlmEventDetail | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const refetch = useCallback(async () => {
    if (!requestId) return;
    setIsLoading(true);
    setError(null);
    try {
      const res = await fetch(`/api/analytics/events/${encodeURIComponent(requestId)}`);
      const data = await parseJsonOrThrow<LlmEventDetail>(res);
      setEvent(data);
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to load trace";
      console.error("[useAnalyticsEventDetail] fetch failed:", err);
      setError(message);
    } finally {
      setIsLoading(false);
    }
  }, [requestId]);

  useEffect(() => {
    setEvent(null);
    if (requestId) void refetch();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [requestId]);

  return { event, isLoading, error, refetch };
}

function useAnalyticsEvents(range: DateRange, filters: EventsFilters) {
  const [page, setPage] = useState<EventsPage | null>(null);
  const [offset, setOffset] = useState(0);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const start = toApiParam(range.start);
  const end = toApiParam(range.end);
  const { status, model, search } = filters;

  useEffect(() => {
    setOffset(0);
  }, [start, end, status, model, search]);

  const refetch = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const params = new URLSearchParams({
        start,
        end,
        limit: String(PAGE_SIZE),
        offset: String(offset),
      });
      if (status) params.set("status", status);
      if (model) params.set("model", model);
      if (search) params.set("search", search);

      const res = await fetch(`/api/analytics/events?${params.toString()}`);
      const data = await parseJsonOrThrow<EventsPage>(res);
      setPage(data);
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to load traces";
      console.error("[useAnalyticsEvents] fetch failed:", err);
      setError(message);
    } finally {
      setIsLoading(false);
    }
  }, [start, end, status, model, search, offset]);

  useEffect(() => {
    void refetch();
  }, [refetch]);

  const nextPage = useCallback(() => {
    setOffset((prev) => (page && prev + PAGE_SIZE < page.total ? prev + PAGE_SIZE : prev));
  }, [page]);

  const prevPage = useCallback(() => {
    setOffset((prev) => Math.max(0, prev - PAGE_SIZE));
  }, []);

  return {
    page,
    offset,
    pageSize: PAGE_SIZE,
    isLoading,
    error,
    refetch,
    nextPage,
    prevPage,
    hasNext: page ? offset + PAGE_SIZE < page.total : false,
    hasPrev: offset > 0,
  };
}

function useAnalyticsSummary(range: DateRange) {
  const [summary, setSummary] = useState<AnalyticsSummary | null>(null);
  const [timeseries, setTimeseries] = useState<Record<MetricKey, TimeseriesPoint[]> | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const start = toApiParam(range.start);
  const end = toApiParam(range.end);

  const refetch = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const params = new URLSearchParams({ start, end });
      const [summaryRes, ...seriesRes] = await Promise.all([
        fetch(`/api/analytics/summary?${params.toString()}`),
        ...METRICS.map((metric) => {
          const p = new URLSearchParams({ start, end, metric });
          return fetch(`/api/analytics/timeseries?${p.toString()}`);
        }),
      ]);

      const summaryData = await parseJsonOrThrow<AnalyticsSummary>(summaryRes);
      const seriesData = await Promise.all(
        seriesRes.map((res) => parseJsonOrThrow<TimeseriesPoint[]>(res))
      );

      setSummary(summaryData);
      setTimeseries(
        METRICS.reduce(
          (acc, metric, index) => ({ ...acc, [metric]: seriesData[index] }),
          {} as Record<MetricKey, TimeseriesPoint[]>
        )
      );
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to load analytics";
      console.error("[useAnalyticsSummary] fetch failed:", err);
      setError(message);
    } finally {
      setIsLoading(false);
    }
  }, [start, end]);

  useEffect(() => {
    void refetch();
  }, [refetch]);

  return { summary, timeseries, isLoading, error, refetch };
}

