async function proxyBackendJson(path: string, init?: RequestInit): Promise<Response> {
  try {
    const backendRes = await backendFetch(path, init);
    const body = await backendRes.text();
    return new Response(body, {
      status: backendRes.status,
      headers: { "Content-Type": "application/json" },
    });
  } catch (error) {
    console.error(`[backend proxy] ${init?.method ?? "GET"} ${path} failed:`, error);
    return Response.json(
      { error: "Could not reach the backend service. Is it running?" },
      { status: 502 }
    );
  }
}

function formatBucketLabel(iso: string, bucket: "hour" | "day"): string {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return iso;
  return bucket === "hour"
    ? date.toLocaleString(undefined, { month: "short", day: "numeric", hour: "numeric" })
    : date.toLocaleDateString(undefined, { month: "short", day: "numeric" });
}

function formatDateTime(iso: string): string {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return iso;
  return date.toLocaleString(undefined, {
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

function presetToRange(preset: DateRangePreset, now: Date = new Date()): DateRange {
  const end = now;
  switch (preset) {
    case "today": {
      const start = new Date(now);
      start.setHours(0, 0, 0, 0);
      return { start, end };
    }
    case "7d":
      return { start: new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000), end };
    case "30d":
      return { start: new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000), end };
    case "all":
      return { start: ALL_TIME_START, end };
  }
}

